def resolve(path, cwd, links):
    if not path or not cwd or links is None:
        return None

    # Ensure cwd is canonical and absolute
    if not cwd.startswith('/'):
        return None

    # Start with cwd if path is relative
    if not path.startswith('/'):
        current = cwd
    else:
        current = ''

    # Split path into components
    components = path.split('/')
    link_count = 0

    i = 0
    while i < len(components):
        comp = components[i]
        i += 1

        # Skip empty and '.' components
        if comp == '' or comp == '.':
            continue

        # Handle '..'
        if comp == '..':
            # Move to parent
            if current == '/':
                pass  # Stay at root
            else:
                last_slash = current.rfind('/')
                if last_slash == 0:
                    current = '/'
                else:
                    current = current[:last_slash]
            continue

        # Regular component - append it
        if current == '/':
            candidate = '/' + comp
        else:
            candidate = current + '/' + comp

        # Check if this is a symlink
        if candidate in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[candidate]

            # Resolve remaining components from the target
            remaining = '/'.join(components[i:])

            # Determine the starting point for target resolution
            if target.startswith('/'):
                # Absolute target
                result = resolve(target + ('/' + remaining if remaining else ''), '/', links)
            else:
                # Relative target - relative to the directory containing the link
                link_dir = candidate[:candidate.rfind('/')]
                if link_dir == '':
                    link_dir = '/'
                result = resolve(target + ('/' + remaining if remaining else ''), link_dir, links)

            return result

        # Not a symlink, just update current
        current = candidate

    # Clean up result - remove trailing slash except for root
    if current == '/':
        return '/'
    else:
        return current

